entries[1236354] = { ["name"] = "Soul Siphon", ["text"] = "40 yd range\n2 sec cast 5 sec cooldown\nCaster slows their target and drains 622547 health over 8 sec, healing the caster for twice the amount drained." }
entries[1236355] = { ["name"] = "Death Knight Rider of the Apocalypse 11.2 Class Set 2pc", ["text"] = "Blood, Unholy\nApocalypse now summons Whitemane for 10 sec. Whitemane's Undeath deals 20% increased damage and infects 1 additional target when it spreads, and her Death Coil deals 35% increased damage.\n\nFrost\nPillar of Frost now summons Trollbane for 10 sec. Trollbane's Icy Fury deals 20% increased damage and his Obliterate deals 15% increased damage." }
entries[1236356] = { ["name"] = "Death Knight Rider of the Apocalypse 11.2 Class Set 4pc", ["text"] = "Blood, Unholy\nCasting Death Coil or Epidemic orders Whitemane to cast her Death Coil or Epidemic alongside you at 125% effectiveness. Your Death Coil deals 40% increased damage to targets affected by Whitemane's Undeath.\n\nFrost\nCasting Obliterate or Frostscythe orders Trollbane to cast his Obliterate or Frostscythe alongside you at 100% effectiveness. Your Obliterate deals 20% increased damage to targets affected by Trollbane's Icy Fury.\n\n(500ms cooldown)" }
entries[1236358] = { ["name"] = "Demon Hunter Aldrachi Reaver 11.2 Class Set 2pc", ["text"] = "Reaver's Glaive damage is increased by 50% and other Physical-only damage is increased by 25%." }
entries[1236360] = { ["name"] = "Demon Hunter Aldrachi Reaver 11.2 Class Set 4pc", ["text"] = "Havoc\nFury of the Aldrachi further empowers Blade Dance when cast after Chaos Strike, increasing slashes to 12.\n\nReaver's Mark now stacks up to 2 times and further empowers Chaos Strike when cast after Blade Dance, applying an additional stack for 100% of normal duration.\n\nVengeance\nFury of the Aldrachi further empowers Soul Cleave when cast after Shear, increasing slashes to 12.\n\nReaver's Mark now stacks up to 2 times and further empowers Shear when cast after Soul Cleave, applying an additional stack for 100% of normal duration." }
entries[1236361] = { ["name"] = "Demon Hunter Fel-Scarred 11.2 Class Set 2pc", ["text"] = "Havoc\nImmolation Aura deals 30% increased damage and increases Chaos Strike damage by 20% while active.\n\nVengeance\nImmolation Aura deals 30% increased damage and increases Soul Cleave damage by 20% while active." }
entries[1236362] = { ["name"] = "Demon Hunter Fel-Scarred 11.2 Class Set 4pc", ["text"] = "Havoc\nEntering demon form now immediately induces a Demonsurge and shatters a demon soul fragment that grants 20% increased damage for 10 sec.\n\nVengeance\nEntering demon form now immediately induces a Demonsurge and shatters a demon soul fragment that grants 20% increased damage for 15 sec.\n\n(100ms cooldown)" }
entries[1236364] = { ["name"] = "Evoker Flameshaper 11.2 Class Set 2pc", ["text"] = "Devastation\nEngulf stokes your Inner Flame, increasing your damage and healing over time by 15% and increasing your chance to gain Essence Burst by 50% for 12 sec. Stacks up to 2 times. Multiple applications may overlap.\n\nPreservation, Augmentation\nEngulf stokes your Inner Flame, increasing your damage and healing over time by 25% and increasing your chance to gain Essence Burst by 50% for 12 sec. Stacks up to 2 times. Multiple applications may overlap." }
entries[1236365] = { ["name"] = "Evoker Flameshaper 11.2 Class Set 4pc", ["text"] = "Devastation\nConsuming Essence Burst during Inner Flame fires an Essence Bomb at your target, damaging nearby enemies for (371% of Spell Power) Arcane, reduced beyond 5 targets.\n\nPreservation, Augmentation\nConsuming Essence Burst during Inner Flame fires an Essence Bomb at your target, healing nearby allies for (250% of Spell Power), reduced beyond 5 targets." }
entries[1236366] = { ["name"] = "Evoker Scalecommander 11.2 Class Set 2pc", ["text"] = "Augmentation\nWhile flying during Deep Breath and for 20 seconds after, you command a squadron of 2 Dracthyr who will attack your targets with Disintegrate and Pyre.\n\nDevastation, Preservation\nWhile flying during Deep Breath and for 10 seconds after, you command a squadron of 2 Dracthyr who will attack your targets with Disintegrate and Pyre." }
entries[1236367] = { ["name"] = "Evoker Scalecommander 11.2 Class Set 4pc", ["text"] = "Devastation\nWhile your squadron is active, your Mass Disintegrate strikes up to 2 additional targets. In addition, your squadron assists you for 5 additional sec.\n\nAugmentation\nWhile your squadron is active, your Mass Eruption strikes up to 2 additional targets. In addition, your squadron assists you for 10 additional sec.\n\nPreservation\nWhile your squadron is active, your Mass Eruption strikes up to 2 additional targets. In addition, your squadron assists you for 5 additional sec." }
entries[1236368] = { ["name"] = "Evoker Chronowarden 11.2 Class Set 2pc", ["text"] = "Tip the Scales' cooldown is reduced by 60 sec." }
entries[1236369] = { ["name"] = "Evoker Chronowarden 11.2 Class Set 4pc", ["text"] = "Temporal Burst causes Chrono Flames to strike 2 additional targets and repeat 15% additional damage or healing, up to a maximum of [(Spell Power * 4.5) * (1 + Versatility)], and increases Essence ability damage and healing by 30%." }
entries[1236370] = { ["name"] = "Hunter Dark Ranger 11.2 Class Set 2pc", ["text"] = "Beast Mastery\nBlack Arrow arrow damage increased by 10% and Bleak Powder damage increased by 20%. The cooldown of Call of the Wild is reduced by 60 sec.\n\nMarksmanship, Survival\nBlack Arrow arrow damage increased by 10% and Bleak Powder damage increased by 20%. The cooldown of Trueshot is reduced by 30 sec." }
entries[1236371] = { ["name"] = "Hunter Dark Ranger 11.2 Class Set 4pc", ["text"] = "Beast Mastery, Marksmanship, Survival\nWithering Fire's Black Arrow damage increased by 50%. Consuming Deathblow has a 50% chance to cause all Black Arrow barrages during your next Withering Fire to fire 1 additional Black Arrow." }
entries[1236372] = { ["name"] = "Hunter Pack Leader 11.2 Class Set 2pc", ["text"] = "Marksmanship, Survival\nPet damage increased by 15% and Beast damage increased by 15%. Summoning a Beast grants 6% haste, mastery, or critical strike chance based on the Beast summoned for 8 sec.\n\nBeast Mastery\nPet damage increased by 5% and Beast damage increased by 15%. Summoning a Beast grants 6% haste, mastery, or critical strike chance based on the Beast summoned for 8 sec." }
entries[1236373] = { ["name"] = "Hunter Pack Leader 11.2 Class Set 4pc", ["text"] = "Summoning a Beast while under the effects of Lead from the Front rouses the nearby wildlife into a Stampede, charging your target and dealing [(300% of Attack Power) * 9] Physical damage to up to 8 enemies over 7 sec." }
entries[1236374] = { ["name"] = "Hunter Sentinel 11.2 Class Set 2pc", ["text"] = "Marksmanship\nRapid Fire damage increased by 25%. When Lunar Storm fades, gain the Boon of Elune, causing your next 2 Aimed Shots to deal Arcane damage and have their damage increased by 10%.\n\nBeast Mastery, Survival\nWildfire Bomb damage increased by 10%. When Lunar Storm fades, gain the Boon of Elune, causing your next 2 Wildfire Bombs to deal Arcane damage and have their initial damage increased by 150%." }
entries[1236375] = { ["name"] = "Hunter Sentinel 11.2 Class Set 4pc", ["text"] = "Marksmanship\nSentinel's damage is increased by 18%. The Boon of Elune is now active for the duration of Lunar Storm at 100% effectiveness.\n\nBeast Mastery, Survival\nSentinel's damage is increased by 20%. The Boon of Elune is now active for the duration of Lunar Storm at 100% effectiveness." }
entries[1236376] = { ["name"] = "Soul Ravel" }
entries[1236377] = { ["name"] = "Monk Master of Harmony 11.2 Class Set 2pc", ["text"] = "Brewmaster\nGaining vitality has an increasing chance to cause your next Tiger Palm to unleash a Harmonic Surge, dealing [180 * (400% of Spell Power) / 100] Nature damage split between your target and other nearby enemies, and [20 * (500% of Spell Power) / 100] healing to up to 5 injured allies.\n\nWindwalker, Mistweaver\nGaining vitality has an increasing chance to cause your next Tiger Palm to unleash a Harmonic Surge, dealing [20 * (400% of Spell Power) / 100] Nature damage split between your target and other nearby enemies, and [90 * (500% of Spell Power) / 100] healing to up to 5 injured allies." }
entries[1236378] = { ["name"] = "Monk Master of Harmony 11.2 Class Set 4pc", ["text"] = "Windwalker, Mistweaver\nCasting Thunder Focus Tea guarantees that your next 2 casts of Tiger Palm will trigger a Harmonic Surge.\n\nBrewmaster\nCasting guarantees that your next 2 casts of Tiger Palm will trigger a Harmonic Surge." }
entries[1236379] = { ["name"] = "Monk Shado-Pan 11.2 Class Set 2pc", ["text"] = "Brewmaster\nFlurry Strikes deal 10% more damage and activating Weapons of Order instantly grants 10 stacks of Flurry Strikes that trigger on your next attack at 70% effectiveness.\n\nWindwalker, Mistweaver\nFlurry Strikes deal 20% more damage and activating Storm, Earth, and Fire instantly grants 10 stacks of Flurry Strikes that trigger on your next attack at 70% effectiveness." }
entries[1236380] = { ["name"] = "Monk Shado-Pan 11.2 Class Set 4pc", ["text"] = "Brewmaster\nFlurry charge generation is increased by 30% and Flurry Strikes triggers every 150 energy spent during Weapons of Order.\n\nWindwalker\nFlurry charge generation is increased by 50% and Flurry Strikes triggers every 120 energy spent during Storm, Earth, and Fire.\n\nMistweaver\nFlurry charge generation is increased by 50% and Flurry Strikes triggers every 150 energy spent during Weapons of Order." }
entries[1236381] = { ["name"] = "Monk Conduit of the Celestials 11.2 Class Set 2pc", ["text"] = "Windwalker\nHeart of the Jade Serpent additionally triggers for 4 sec at 100% effectiveness after you cast Slicing Winds.\n\nBrewmaster, Mistweaver\nHeart of the Jade Serpent additionally triggers for 8 sec at 100% effectiveness after you cast Thunder Focus Tea.\n\n(1s cooldown)" }
entries[1236382] = { ["name"] = "Monk Conduit of the Celestials 11.2 Class Set 4pc", ["text"] = "Heart of the Jade Serpent increases your haste by 10% while active and for 4 sec afterwards." }
entries[1236383] = { ["name"] = "Paladin Herald of the Sun 11.2 Class Set 2pc", ["text"] = "Retribution\nDawnlight's healing and damage is increased by 30% and you gain Solar Wrath after Avenging Wrath fades causing Sun's Avatar's effect to linger for an additional [10][10] sec.\n\nProtection\nDawnlight's healing and damage is increased by 30% and you gain Solar Wrath after Avenging Wrath fades causing Sun's Avatar's effect to linger for an additional [10][10] sec.\n\nHoly (Avenging Wrath)\nDawnlight's healing and damage is increased by 60% and you gain Solar Wrath after Avenging Wrath fades causing Sun's Avatar's effect to linger for an additional 10[10][10] sec." }
entries[1236384] = { ["name"] = "Paladin Herald of the Sun 11.2 Class Set 4pc", ["text"] = "Retribution\nSolar Wrath increases the effectiveness of your Holy Power spenders by 15% and grants you [2][2] Dawnlight.\n\nProtection\nSolar Wrath increases the effectiveness of your Holy Power spenders by 15% and grants you [2][2] Dawnlight.\n\nHoly (Avenging Wrath)\nSolar Wrath increases the effectiveness of your Holy Power spenders by 30% and grants you 2[2][2] Dawnlight." }
entries[1236385] = { ["name"] = "Soul Strafe" }
entries[1236386] = { ["name"] = "Renew Ally", ["text"] = "100 yd range\nInstant\nArator renews his ally." }
entries[1236388] = { ["name"] = "Barrier Protection", ["text"] = "Instant\nThis creature is being shielded by a protective barrier." }
entries[1236389] = { ["name"] = "Paladin Lightsmith 11.2 Class Set 2pc", ["text"] = "Protection\nHammer and Anvil's damage is increased by 15% and it can also be activated by at 40% effectiveness.\n\nRetribution\nHammer and Anvil's healing is increased by 15% and it can also be activated by Crusader Strike at 40% effectiveness.\n\nHoly\nHammer and Anvil's healing is increased by 15% and it can also be activated by Crusader Strike at 75% effectiveness.\n\n(750ms cooldown)" }
entries[1236390] = { ["name"] = "Paladin Lightsmith 11.2 Class Set 4pc", ["text"] = "Hammer and Anvil also grants a stack of Masterwork, causing your next Holy Armament to cast one Lesser version of itself on a nearby ally for each stack." }
entries[1236391] = { ["name"] = "Paladin Templar 11.2 Class Set 2pc", ["text"] = "Your Empyrean Hammer deals 20% increased critical strike damage and its critical strikes have 50% chance to grant an additional stack of Light's Deliverance.\n(Proc chance: 50%)" }
entries[1236392] = { ["name"] = "Paladin Templar 11.2 Class Set 4pc", ["text"] = "Holy, Protection\nHammer of Light deals 35% increased damage to its primary target, strikes 3 additional secondary targets, and can now be cast 1 more time after Eye of Tyr.\n\nRetribution\nHammer of Light deals 35% increased damage to its primary target, strikes 3 additional secondary targets, and can now be cast 1 more time after Wake of Ashes." }
entries[1236394] = { ["name"] = "Priest Oracle 11.2 Class Set 2pc", ["text"] = "Holy, Shadow\nCasting Prayer of Mending heals your target for (1400% of Spell Power).\n\nDiscipline\nThe first bolt of each Penance cast damages or heals for 200% more." }
entries[1236395] = { ["name"] = "Priest Oracle 11.2 Class Set 4pc", ["text"] = "Casting Premonition of Piety or Premonition of Solace grants 2 stacks of Premonition of Insight at 100% effectiveness. Consuming a stack of Premonition of Insight increases your Haste by 1.0% for 10 sec. Multiple applications may overlap." }
entries[1236396] = { ["name"] = "Priest Voidweaver 11.2 Class Set 2pc", ["text"] = "Discipline\nVoid Blast and Penance damage is increased by 30% and Void Blast's cast time is reduced by 20%.\n\nHoly\nVoid Blast damage is increased by 30% and Void Blast's cast time is reduced by 20%.\n\nShadow\nVoid Blast damage is increased by 30% and Void Blast's cast time is reduced by 20%. Void Blast's cooldown is reduced by 50%." }
entries[1236397] = { ["name"] = "Priest Voidweaver 11.2 Class Set 4pc", ["text"] = "Discipline\nVoid Blast now also causes Entropic Rift to grow, Collapsing Void increases Entropic Rift's damage by an additional 10%, and the damage of your next Mind Blast is increased by up to 300% based on the size of Entropic Rift when it collapses.\n\nHoly\nVoid Blast now also causes Entropic Rift to grow, Collapsing Void increases Entropic Rift's damage by an additional 10%, and the damage of your next Void Torrent is increased by up to 200% based on the size of Entropic Rift when it collapses.\n\nShadow\nVoid Blast now also causes Entropic Rift to grow, Collapsing Void increases Entropic Rift's damage by an additional 10%, and the damage of your next Void Torrent is increased by up to 60% based on the size of Entropic Rift when it collapses." }
entries[1236398] = { ["name"] = "Priest Archon 11.2 Class Set 2pc", ["text"] = "Shadow\nHalos generate an additional 10 Insanity over 5 sec and Resonant Energy additionally increases the damage of your Devouring Plague by 5.0%.\n\nDiscipline, Holy\nHalos reduce the cooldown of your Holy Word: Serenity and Holy Word: Sanctify by 5 sec and Resonant Energy additionally increases the healing of your Holy Words by 5.0%." }
entries[1236399] = { ["name"] = "Priest Archon 11.2 Class Set 4pc", ["text"] = "Discipline, Shadow\nWhile Power Surge is active, every 2 casts of Devouring Plague adds another Halo to the effect at 100% effectiveness, up to 2 times.\n\nHoly\nWhile Power Surge is active, every 2 casts of Holy Word: Serenity or Holy Word: Sancitify adds another Halo to the effect at 100% effectiveness, up to 2 times." }
entries[1236400] = { ["name"] = "Rogue Deathstalker 11.2 Class Set 2pc", ["text"] = "Assassination\nShiv increases the effectiveness of all Deathstalker damage effects and damage bonuses by 60% while active.\n\nOutlaw, Subtlety\nSymbols of Death increases the effectiveness of all Deathstalker damage effects and damage bonuses by 40% while active." }
entries[1236401] = { ["name"] = "Rogue Deathstalker 11.2 Class Set 4pc", ["text"] = "Assassination\nShiv has 3 sec increased duration and consumes an application of your active Deathstalker's Mark when activated.\n\nOutlaw, Subtlety\nSymbols of Death has 3 sec increased duration and consumes an application of your active Deathstalker's Mark when activated." }
entries[1236402] = { ["name"] = "Rogue Fatebound 11.2 Class Set 2pc", ["text"] = "Outlaw\nGhostly Strike deals 50% increased damage and has 4 sec increased duration.\n\nEdge Case now flips an additional Fatebound Coin and activating Ghostly Strike triggers its effect.\n\nAssassination, Subtlety\nKingsbane deals 10% increased damage and has 4 sec increased duration.\n\nEdge Case now flips an additional Fatebound Coin and activating Kingsbane triggers its effect." }
entries[1236403] = { ["name"] = "Rogue Fatebound 11.2 Class Set 4pc", ["text"] = "Outlaw\nHaving a lucky Fatebound Coin reduces the cooldown of Adrenaline Rush by 30.0 sec and Ghostly Strike by 15.0 sec.\n\nAssassination, Subtlety\nHaving a lucky Fatebound Coin reduces the cooldown of Deathmark by 30.0 sec and Kingsbane by 15.0 sec." }
entries[1236404] = { ["name"] = "Rogue Trickster 11.2 Class Set 2pc", ["text"] = "Unseen Blade deals 35% increased damage and has a 35% chance to strike twice." }
entries[1236405] = { ["name"] = "Rogue Trickster 11.2 Class Set 4pc", ["text"] = "Coup de Grace may now be activated a second time within 5 sec, dealing 150% of normal damage." }
entries[1236406] = { ["name"] = "Shaman Farseer 11.2 Class Set 2pc", ["text"] = "Ancestral Swiftness summons an empowered Ancestor for 15 sec that deals 10% increased damage and healing." }
entries[1236407] = { ["name"] = "Shaman Farseer 11.2 Class Set 4pc", ["text"] = "Restoration\nAncestral Swiftness increases the damage and healing of your spells by 25%, reduces the mana cost of your spells by 25%, and increases the recharge rate of Lava Burst and Riptide by 50% for 8 sec.\n\nElemental, Enhancement\nAncestral Swiftness increases the damage and healing of your spells by 25%, reduces the mana cost of your spells by 25%, and increases the recharge rate of Lava Burst by 50% for 8 sec." }
entries[1236408] = { ["name"] = "Shaman Stormbringer 11.2 Class Set 2pc", ["text"] = "Enhancement, Restoration\nAscendance has a 100% chance to grant a charge of Tempest and every 8 Awakening Storms now activates Ascendance for 6.0 sec.\n\nElemental\nAscendance has a 100% chance to grant a charge of Tempest and every 9 Awakening Storms now activates Ascendance for 6.0 sec.\n\n(100ms cooldown)" }
entries[1236409] = { ["name"] = "Shaman Stormbringer 11.2 Class Set 4pc", ["text"] = "Elemental, Restoration\nNature damage increased by 3.0%, and Ascendance empowers your next 2 Tempests to gather a storm above that deals (960% of Spell Power) Nature damage to its primary target and reduced damage to nearby enemies after 1.5 sec.\n\nEnhancement\nNature damage increased by 5.0%, and Ascendance empowers your next 2 Tempests to gather a storm above that deals (400% of Attack Power) Nature damage to its primary target and reduced damage to nearby enemies after 1.5 sec.\n\n(100ms cooldown)" }
entries[1236410] = { ["name"] = "Shaman Totemic 11.2 Class Set 2pc", ["text"] = "Elemental, Restoration\nAfter you consume all the Whirling Element Motes, you cast Downpour at 200% effectiveness at your Surging Totem's location.\n\nEnhancement\nAfter you consume all the Whirling Element Motes, your Surging Totem casts Primordial Storm at 200% effectiveness at its location." }
entries[1236411] = { ["name"] = "Shaman Totemic 11.2 Class Set 4pc", ["text"] = "Elemental, Restoration\nAfter casting Downpour, your next Chain Heal, Healing Wave, or Healing Surge casts again at 150% effectiveness.\n\nEnhancement\nAfter casting Primordial Storm, your next Lava Lash or Fire Nova casts again at 150% effectiveness.\n\n(500ms cooldown)" }
entries[1236412] = { ["name"] = "Snow Patch" }
entries[1236413] = { ["name"] = "Warlock Hellcaller 11.2 Class Set 2pc", ["text"] = "Demonology, Destruction\nMark of Xavius increases Blackened Soul damage by an additional 3% per stack. Malevolence increases the stack count of Wither by an additional 2 stacks.\n\nAffliction\nMark of Xavius increases Blackened Soul damage by an additional 6% per stack. Malevolence increases the stack count of Wither by an additional 2 stacks." }
entries[1236414] = { ["name"] = "Warlock Hellcaller 11.2 Class Set 4pc", ["text"] = "Demonology, Destruction\nCasting Malevolence grants 2 stacks of Backdraft and prevents Blackened Soul from consuming stacks while dealing damage 15% faster for 8 sec.\n\nAffliction\nCasting Malevolence grants 2 stacks of Tormented Crescendo and prevents Blackened Soul from consuming stacks while dealing damage 25% faster for 8 sec." }
entries[1236415] = { ["name"] = "Warlock Soul Harvester 11.2 Class Set 2pc", ["text"] = "Shadow of Death unleashes your demonic soul to assault your current target for 9 sec, dealing (279.306% of Spell Power) Shadow damage and (186.209% of Spell Power) Shadow damage to enemies within 10 yds with each swipe." }
entries[1236416] = { ["name"] = "Warlock Soul Harvester 11.2 Class Set 4pc", ["text"] = "Demonic Soul damage increased by 45% and Wicked Reaping damage increased by 45%. Your demonic soul generates 1 Soul Shard every 3 sec while assaulting enemies." }
entries[1236417] = { ["name"] = "Warlock Diabolist 11.2 Class Set 2pc", ["text"] = "Affliction, Destruction\nCasting Chaos Bolt, Rain of Fire, or Shadowburn summons a Demonic Oculus, up to 3. Consuming Demonic Art flings your Demonic Oculi at your current target, exploding for (502.813% of Spell Power) Fire damage and (335.172% of Spell Power) Fire damage to enemies within 10 yds.\n\nDemonology\nHand of Gul'dan cast at full power summons a Demonic Oculus, up to 3. Consuming Demonic Art flings your Demonic Oculi at your current target, exploding for (502.813% of Spell Power) Fire damage and (335.172% of Spell Power) Fire damage to enemies within 10 yds." }
entries[1236418] = { ["name"] = "Warlock Diabolist 11.2 Class Set 4pc", ["text"] = "Demonic Oculi analyze the battle while active and deliver information to you as they explode, increasing your Intellect by 2% for 10 sec." }
entries[1236419] = { ["name"] = "Warrior Colossus 11.2 Class Set 2pc", ["text"] = "Demolish damage increased by 20% and critical strike damage of your abilities is increased by up to 20% on targets affected by your Demolish for 10 sec based on the number of stacks of Colossal Might consumed." }
entries[1236420] = { ["name"] = "Warrior Colossus 11.2 Class Set 4pc", ["text"] = "Arms\nDemolish increases the critical strike chance of your next 1 Mortal Strike by 100%. Mortal Strike critical strikes increase your Rend and Deep Wounds damage by 80% for 8 sec.\n\nFury, Protection\nDemolish increases the critical strike chance of your next 1 Shield Slam by 100%. Shield Slam critical strikes increase your Rend and Deep Wounds damage by 80% for 8 sec." }
entries[1236421] = { ["name"] = "Warrior Mountain Thane 11.2 Class Set 2pc", ["text"] = "Thunder Blast has a 35% chance to call down 5 Ionizing Strikes on affected targets. Each strike deals (150% of Attack Power) Nature damage." }
entries[1236422] = { ["name"] = "Warrior Mountain Thane 11.2 Class Set 4pc", ["text"] = "Ionizing Strikes deal 100% more damage and when you trigger Ionizing Strikes, you gain a charge of Thunder Blast and your next Thunder Blast deals 100% additional damage." }
entries[1236423] = { ["name"] = "Warrior Slayer 11.2 Class Set 2pc", ["text"] = "Execute damage increased by 10% and Executes from Sudden Death have a 10% chance per stack of Overwhelmed on the target to trigger a Slayer's Strike at 100% effectiveness." }
entries[1236424] = { ["name"] = "Warrior Slayer 11.2 Class Set 4pc", ["text"] = "Arms\nOverpower damage increased by 10% and Overpower has a 2% chance per stack of Overwhelmed on the target to trigger Reap the Storm at 150% effectiveness.\n\nFury, Protection\nRaging Blow damage increased by 10% and Raging Blow has a 2% chance per stack of Overwhelmed on the target to trigger Reap the Storm at 150% effectiveness.\n\n(500ms cooldown)" }
