entries[1236461] = { ["name"] = "Gleeful Glamour - Blood Elf", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Wild Magic , Eversinging Dust (2)\nOptional Reagents:\nProfession:\nMidnight Enchanting (5)\nTrainer:\nJennara Sunglow\nZone:\nSilvermoon City\nCost:\n60\n\nUse: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\nLasts 30-60 min. based on the quality of the Gleeful Glamour." }
entries[1236463] = { ["name"] = "Gleeful Glamour - Dark Iron Dwarf", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Primal Energy , Eversinging Dust (2)\nOptional Reagents:\nProfession:\nMidnight Enchanting (45)\nTrainer:\nJennara Sunglow\nZone:\nSilvermoon City\nCost:\n60\n\nUse: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\nLasts 30-60 min. based on the quality of the Gleeful Glamour." }
entries[1236464] = { ["name"] = "Gleeful Glamour - Haranir", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Primal Energy , Eversinging Dust (2)\nOptional Reagents:\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n150\n1500\n\nUse: Don the mask, magically altering your appearance to that of another one of Azeroth's residents.\n\nLasts 30-60 min. based on the quality of the Gleeful Glamour." }
