entries[1236486] = { ["name"] = "Runed Refulgent Copper Rod", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nRefulgent Copper Rod , Eversinging Dust (5)\nOptional Reagents:\nProfession:\nMidnight Enchanting (1)\n\nRuned Refulgent Copper Rod\nBinds when equipped\nEnchanting Tool\n+ 43 Random Stat 1\nEquip: +8 Midnight Enchanting Skill\n78\nRequires Midnight Enchanting\n(1)\n\"Serves as a runed enchanting rod.\"" }
entries[1236487] = { ["name"] = "Runed Brilliant Silver Rod", ["text"] = "2 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nBrilliant Silver Ore (5), Eversinging Dust (20), Radiant Shard (5), Dawn Crystal (2), Silvermoon Weapon Wrap\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Reputable Rods\n\nRuned Brilliant Silver Rod\nBinds when equipped\nEnchanting Tool\n+ 45 Random Stat 1\nEquip: +18 Midnight Enchanting Skill\n78\nRequires Midnight Enchanting\n(1)\n\"Serves as a runed enchanting rod.\"" }
entries[1236488] = { ["name"] = "Runed Dazzling Thorium Rod", ["text"] = "2 sec cast 2\nTools: Runed Enchanting Rod\nReagents:\nFused Vitality (20), Dazzling Thorium (3), Eversinging Dust (30), Radiant Shard (10), Dawn Crystal (4), Silvermoon Weapon Wrap\nOptional Reagents:\nVendor:\nLyna\nZone:\nSilvermoon City\nCost:\n150\n\nVendor:\nLyrendal\nZone:\nSilvermoon City\nCost:\n150\n\nRuned Dazzling Thorium Rod\nBinds when picked up\nEnchanting Tool\n+ 48 Random Stat 1\nEquip: +18 Midnight Enchanting Skill\n78\nRequires Midnight Enchanting\n(1)\n\"Serves as a runed enchanting rod.\"" }
entries[1236489] = { ["name"] = "Thalassian Spellweaver's Wand", ["text"] = "2 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nEversinging Dust (15), Radiant Shard (3)\nOptional Reagents:\nProfession Trainer:\nMidnight Enchanting (40)\nCost:\n150\n\nThalassian Spellweaver's Wand\nBinds when equipped\nRanged Wand\n3 - 6 Shadow Damage Speed 2.00\n(2.3 damage per second)\n+26 Intellect\n+7 Stamina\n+ 5 Random Stat 1\n+ 5 Random Stat 2\nDurability 90 / 90\n72" }
entries[1236490] = { ["name"] = "Magister's Grand Focus", ["text"] = "2 sec cast 3\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (10), Tormented Tantalum , Radiant Shard (20), Dawn Crystal , Silvermoon Weapon Wrap , Spark (#401) (2)\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Worthy Wands\n\nMagister's Grand Focus\nBinds when picked up\nRanged Wand\n3 - 6 Fire Damage Speed 2.00\n(2.3 damage per second)\n+26 Intellect\n+7 Stamina\n+ 5 Random Stat 1\n+ 5 Random Stat 2\nDurability 110 / 110\n70" }
entries[1236491] = { ["name"] = "Thalassian Phoenix Oil", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (5), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nProfession Trainer:\nMidnight Enchanting (20)\nCost:\n110\n\nThalassian Phoenix Oil\n\nUse: Coat your weapon with Thalassian Phoenix Oil, increasing your Critical Strike and Haste by 13 for 120 min.\n\nCannot be applied to items lower than level 120.\n78\n\"The bottle contains what appears to be liquid fire and radiates warmth.\"" }
entries[1236492] = { ["name"] = "Oil of Dawn", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Light (5), Petrified Root (2), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nSpecialization:\nTransitories, Tonics, and Tools - Excellent Expendables\n\nOil of Dawn\n\nUse: Coat your weapon with Oil of Dawn. Your healing spells and abilities have a chance to resonate with the oil and shield your target, absorbing the next 1503 damage they take.\n\nLasts 120 min.\n\nCannot be applied to items lower than level 120.\n78\n\"A vial of holy oil blessed by the Sunwell.\"" }
entries[1236493] = { ["name"] = "Smuggler's Enchanted Edge", ["text"] = "2 sec cast\nTools: Runed Enchanting Rod\nReagents:\nMote of Primal Energy (5), Petrified Root (2), Sunglass Vial , Eversinging Dust (5)\nOptional Reagents:\nDrop:\nLithiel Cinderfury\nZone:\nMurder Row\n\nSmuggler's Enchanted Edge\n\nUse: Coat your weapon with Smuggler's Enchanted Edge. This oil has a chance to activate whenever you deal damage, inflicting ( 1 * 1002 ) Arcane damage to the target.\n\nLasts 120 min.\n\nCannot be applied to items lower than level 120.\n78\n\"More of a magical toxic sludge than an oil, really.\"" }
